// Локальный скрипт инициализации confetti от ИИ
window.confetti = window.confetti || function(options) {
    var canvas = document.createElement('canvas');
    canvas.style.position = 'fixed';
    canvas.style.top = '0px';
    canvas.style.left = '0px';
    canvas.style.width = '100%';
    canvas.style.height = '100%';
    canvas.style.pointerEvents = 'none';
    canvas.style.zIndex = options.zIndex || 100;
    document.body.appendChild(canvas);

    var ctx = canvas.getContext('2d');
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;

    var particles = [];
    var colors = options.colors || ['#22c55e', '#3b82f6', '#f59e0b', '#ec4899'];

    for (var i = 0; i < (options.particleCount || 50); i++) {
        particles.push({
            x: window.innerWidth * (options.origin && options.origin.x !== undefined ? options.origin.x : 0.5),
            y: window.innerHeight * (options.origin && options.origin.y !== undefined ? options.origin.y : 0.5),
            vx: Math.cos(options.angle * Math.PI / 180 || 0) * (Math.random() * 15 + 5) + (Math.random() - 0.5) * (options.spread || 45),
            vy: Math.sin(options.angle * Math.PI / 180 || 0) * (Math.random() * 15 + 5) - (Math.random() * 20),
            color: colors[i % colors.length],
            radius: Math.random() * 6 + 4,
            alpha: 1
        });
    }

    function draw() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        var alive = false;
        particles.forEach(function(p) {
            p.x += p.vx * 0.1;
            p.y += p.vy * 0.1 + 0.5; // гравитация
            p.alpha -= 0.01;
            if (p.alpha > 0) {
                alive = true;
                ctx.fillStyle = p.color;
                ctx.globalAlpha = p.alpha;
                ctx.beginPath();
                ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
                ctx.fill();
            }
        });
        if (alive) {
            requestAnimationFrame(draw);
        } else {
            if (canvas.parentNode) canvas.parentNode.removeChild(canvas);
        }
    }
    draw();
};